import {build,validateSave} from './engine.js?v=room-to-grow-1';
import {serializeCity} from './save.js?v=room-to-grow-1';
import {BUSINESSES,businessOffer} from './business.js?v=room-to-grow-1';
import {neighborhoodSnapshot} from './neighborhood-report.js?v=room-to-grow-1';
export function analyzeBusinessSite(city,type,point){
 if(!Object.hasOwn(BUSINESSES,type))throw Error('Choose a business deal.');
 if(!Number.isInteger(point?.x)||!Number.isInteger(point?.y)||point.x<0||point.y<0||point.x>=city.size||point.y>=city.size)throw Error('Choose whole tile coordinates inside the city.');
 const projected=validateSave(JSON.parse(serializeCity(city))),center={x:Math.min(city.size-1,point.x+1),y:Math.min(city.size-1,point.y+1)},snapshot=()=>({balance:projected.stats.balance,businessIncome:projected.stats.businessIncome,funds:projected.funds,neighborhood:neighborhoodSnapshot(projected,center,8)}),before=snapshot();
 // A temporary permit lets a mayor inspect the consequences before deciding.
 // It exists only in this detached model and cannot accept the actual offer.
 const permit=businessOffer(projected,type);permit.offered??=projected.month;permit.accepted=true;
 const result=build(projected,type,[point]);if(!result.ok)return{ok:false,error:result.error,point:{...point},before};
 return{ok:true,point:{...point},before,after:snapshot(),monthlyStipend:BUSINESSES[type].stipend};
}
export function suggestedBusinessSites(city,type){const size=BUSINESSES[type]?.size;if(!size)return[];const candidates=[],middle=(city.size-size)/2;
 for(let y=0;y<=city.size-size;y++)for(let x=0;x<=city.size-size;x++){const elevation=city.tiles[y*city.size+x].elevation;let clear=true;for(let dy=0;dy<size&&clear;dy++)for(let dx=0;dx<size;dx++){const t=city.tiles[(y+dy)*city.size+x+dx];if(t.radiation||t.elevation!==elevation||t.type||t.rubble||t.rail||t.highway||t.terrain==='water'){clear=false;break;}}if(clear)candidates.push({x,y});}
 candidates.sort((a,b)=>(a.x-middle)**2+(a.y-middle)**2-((b.x-middle)**2+(b.y-middle)**2)||a.y-b.y||a.x-b.x);if(!candidates.length)return[];const first=candidates[0],second=candidates.find(p=>Math.hypot(p.x-first.x,p.y-first.y)>=12)||candidates.find(p=>Math.hypot(p.x-first.x,p.y-first.y)>=size)||first;return[first,second];
}
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n===null?'No residents':Number(n).toLocaleString('en-US',{maximumFractionDigits:1});
export function showBusinessSiteAnalysis(ui,type,back){const c=ui.city(),d=BUSINESSES[type];if(!d)return;const suggested=suggestedBusinessSites(c,type);ui.dialog(d.name+' · site impact',`<p>Compare two proposed 3 × 3 sites before accepting or placing this deal. Coordinates identify the northwest corner; use Inspect a tile on the city map to find them. Starting suggestions check clear, level terrain; Compare sites checks all construction rules.</p><div class="actions">${['A','B'].map((label,i)=>`<fieldset><legend>Site ${label}</legend><label>Column<input id="businessSiteX${i}" type="number" min="1" max="${c.size}" step="1" value="${(suggested[i]?.x??Math.floor(c.size/2))+1}"></label><label>Row<input id="businessSiteY${i}" type="number" min="1" max="${c.size}" step="1" value="${(suggested[i]?.y??Math.floor(c.size/2))+1}"></label></fieldset>`).join('')}</div><button id="compareBusinessSites" class="primary">Compare sites</button><div id="businessSiteResults" aria-live="polite"></div><p>No deal is accepted, no building is placed, and no month advances in your city. Results describe immediate conditions at current development. Future growth, operating costs of new services, disasters and random toxic clouds are not forecast. Local scores use residents within eight tiles of each proposed building’s center.</p><button id="backBusinessSites">Back to business deals</button>`);
 document.getElementById('compareBusinessSites').onclick=()=>{const results=[0,1].map(i=>{try{return analyzeBusinessSite(c,type,{x:Number(document.getElementById('businessSiteX'+i).value)-1,y:Number(document.getElementById('businessSiteY'+i).value)-1});}catch(e){return{ok:false,error:e.message};}});document.getElementById('businessSiteResults').innerHTML=results.map((r,i)=>`<article><h3>Site ${i?'B':'A'}</h3>${!r.ok?`<p>${escape(r.error||'This location cannot be built.')}</p>`:`<p>Buildable at column ${r.point.x+1}, row ${r.point.y+1}. Stipend: §${fmt(r.monthlyStipend)}/month while standing. Immediate construction charge: §${fmt(r.before.funds-r.after.funds)}.</p><div class="table-scroll"><table><thead><tr><th>Measure</th><th>Current</th><th>With this site</th></tr></thead><tbody>${[['City monthly balance (§)','balance'],['Business income (§/month)','businessIncome']].map(([label,key])=>`<tr><td>${label}</td><td>${fmt(r.before[key])}</td><td>${fmt(r.after[key])}</td></tr>`).join('')}${[['Residents in local area','residents'],['Local crime / 100','crime'],['Local air pollution / 100','airPollution'],['Local water pollution / 100','waterPollution'],['Local land value / 100','landValue']].map(([label,key])=>`<tr><td>${label}</td><td>${fmt(r.before.neighborhood[key])}</td><td>${fmt(r.after.neighborhood[key])}</td></tr>`).join('')}</tbody></table></div>`}</article>`).join('');};document.getElementById('backBusinessSites').onclick=back;
}
